{tab==='style'&&<>{draft.kind==='metric'?<><Field label="主题颜色"><div className="color-picker">{['#3576ee','#22a2a1','#f2ad43','#6476b8','#e16f58'].map(color=><button key={color} title={color} className={draft.color===color?'chosen':''} style={{background:color}} onClick={()=>set('color',color)}>{draft.color===color&&<Check size={15}/>}</button>)}</div></Field><Field label="小数位"><select value={draft.decimals} onChange={e=>set('decimals',Number(e.target.value))}>{[0,1,2].map(n=><option key={n} value={n}>{n} 位</option>)}</select></Field>{draft.type==='pie'&&<><Field label="饼图样式"><select value={draft.donut===false?'pie':'donut'} onChange={e=>set('donut',e.target.value==='donut')}><option value="donut">环形</option><option value="pie">饼形</option></select></Field><label className="check-row"><input type="checkbox" checked={draft.showLegend!==false} onChange={e=>set('showLegend',e.target.checked)}/>显示图例</label></>}</>:draft.kind==='image'?<Field label="图片显示方式"><select value={draft.fit||'contain'} onChange={e=>set('fit',e.target.value)}><option value="contain">等比适应</option><option value="cover">填充裁剪</option></select></Field>:draft.kind==='text'?<><Field label="字号"><select value={draft.fontSize||16} onChange={e=>set('fontSize',Number(e.target.value))}>{[14,16,18,24,32].map(n=><option value={n} key={n}>{n} px</option>)}</select></Field><Field label="对齐"><select value={draft.align||'left'} onChange={e=>set('align',e.target.value)}><option value="left">左对齐</option><option value="center">居中</option><option value="right">右对齐</option></select></Field><label className="check-row"><input type="checkbox" checked={draft.bold||false} onChange={e=>set('bold',e.target.checked)}/>粗体</label></>:<p className="muted">网页遵循来源页面的样式，组件会自动适应尺寸。</p>}</>}
