const navigate=async(type,id)=>{try{if(dirtyConfig.current&&!window.confirm('当前组件配置尚未应用，放弃这些配置并继续？'))return;clearTimeout(timer.current);await saveNow();location.hash=type==='boards'?'':`${type}/${id||''}`;}catch(e){setError(e.message);notify('请先重试保存，再离开当前看板。');}};
useEffect(()=>{const route=async()=>{setLoading(true);setError('');setAIReset();try{const hash=location.hash.slice(1);if(hash.startsWith('board/')){const b=await api('/boards/'+hash.slice(6));loadBoard(b);setPage('editor');setView(false);const recovery=localStorage.getItem('northstar:recovery:'+b.id);if(recovery&&window.confirm('发现上次未保存的修改，是否恢复？')){const local=JSON.parse(recovery);if(local.revision===b.revision){boardRef.current={...local,revision:b.revision};seq.current=1;setBoard(boardRef.current);}else notify('服务器版本已变化，请保留恢复副本后处理。');}}else if(hash.startsWith('view/')){const b=await api('/versions/'+hash.slice(5));loadBoard(b);setPage('editor');setView(true);}else{setPage(['metrics','templates','spec'].includes(hash)?hash:'boards');setView(false);loadBoard(nullSafe());await refreshBoards();}}catch(e){setError(e.message);}finally{setLoading(false);}};function nullSafe(){boardRef.current=null;boardId.current=null;return {id:null,components:[],name:'',revision:0};}function setAIReset(){setAiOpen(false);setAiPlan(null);setAiError('');aiController.current?.abort();setAiBusy(false);}route();window.addEventListener('hashchange',route);api('/status').then(setStatus).catch(e=>setError(e.message));return()=>window.removeEventListener('hashchange',route);},[]);
useEffect(()=>{const handler=e=>{if(seq.current!==savedSeq.current){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler);},[]);
const selectedComponent=board?.components?.find(c=>c.id===selected);
const select=id=>{if(id===selected)return;if(dirtyConfig.current&&!window.confirm('当前组件配置尚未应用，放弃这些配置并切换？'))return;dirtyConfig.current=false;setSelected(id);};
