const add=(c,pos)=>{if(pos)c={...c,...pos};const items=pos?place(boardRef.current.components,c):append(boardRef.current.components,c);updateItems(items);setSelected(c.id);setAiOpen(false);notify(`已添加${c.kind==='metric'?metricBy(c.metricId).name:{text:'文本',image:'图片',web:'网页'}[c.kind]}`);};
const remove=id=>{updateItems(boardRef.current.components.filter(c=>c.id!==id));if(selected===id)setSelected(null);notify('组件已删除，可撤销恢复。');};
