useEffect(()=>{const key=e=>{if(page!=='editor'||view||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if((e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.altKey&&e.key.startsWith('Arrow')&&selectedComponent){e.preventDefault();const c=selectedComponent;updateItems(place(boardRef.current.components,{...c,x:c.x+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0),y:c.y+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)}));}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[page,view,selectedComponent,historyCount]);
