const publish=async()=>{try{if(dirtyConfig.current){notify('请先应用组件配置。');return;}const err=validateBoard(boardRef.current,{publish:true});if(err){setError(err);notify(err);return;}clearTimeout(timer.current);await saveNow();const before=boardRef.current;const result=await api('/boards/'+before.id+'/publish',post({revision:before.revision}));if(boardRef.current?.id===result.id){boardRef.current={...boardRef.current,revision:result.revision,published:result.published};setBoard(boardRef.current);}notify('已发布独立版本，现在可以分享。');await refreshBoards();}catch(e){setError(e.message);}};
